    .arg(Arg::new("cfg")
        .action(ArgAction::Set)
        .require_equals(true)
        .long("config"))
    .try_get_matches_from(vec![
        "prog", "--config=file.conf"
    ]);

assert!(res.is_ok());
```

Setting `require_equals` and *not* supplying the equals will cause an
error.

```rust
# use clap_builder as clap;
