```rust
# use clap_builder as clap;
# use clap::{Command, Arg, error::ErrorKind, value_parser};
fn is_numeric(val: &str) -> Result<(), String> {
    match val.parse::<i64>() {
        Ok(..) => Ok(()),
        Err(..) => Err(String::from("value wasn't a number!")),
    }
}

